use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored, in order of preference.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            c => cur.push(c),
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            _ => return None,
        }
    }
    Some(out)
}

/// Parse a stored value: either a JSON array of strings, or one URL per line
/// (commas also accepted), with blank lines and `#` comments ignored.
fn parse_urls(raw: &str) -> Vec<String> {
    let candidates = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .lines()
            .flat_map(|l| l.split(','))
            .map(|s| s.to_string())
            .collect(),
    };
    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !out.iter().any(|e| e == u) {
            out.push(u.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present; an empty or missing
        // subscription store is a configuration error, not a valid output.
        panic!("subscriptions store holds no feed URLs");
    }
}

export!(Node);
```

